// Console prefix patch - extracted for popup entry
export function applyConsolePatch(prefix = '[AI Prompt Queue]') {
  if (console.__aiPromptQueuePatched) return;
  console.__aiPromptQueuePatched = true;
  ['log', 'info', 'warn', 'error', 'debug'].forEach((method) => {
    const original = console[method]?.bind(console);
    if (original) {
      console[method] = (...args) => {
        const first = args[0];
        if (typeof first === 'string') {
          original(`${prefix} ${first}`, ...args.slice(1));
        } else {
          original(prefix, ...args);
        }
      };
    }
  });
}

// DOM + UI helpers used by popup.js

export const PROMPT_SEPARATOR = [
  '---------------------------------------------------',
  '------------------Next prompt------------------',
  '---------------------------------------------------',
].join('\n');

export function parsePrompts(text, separator = PROMPT_SEPARATOR) {
  if (typeof text !== 'string') return [];
  const chosenSeparator = typeof separator === 'string' && separator.length > 0
    ? separator
    : PROMPT_SEPARATOR;
  // Prefer explicit separator blocks for multi-line prompts; fall back to per-line
  const separatorChunks = text.split(chosenSeparator);
  const chunks = separatorChunks.length > 1
    ? separatorChunks
    : text.split(/\r?\n/);

  return chunks
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
}

export function applyTheme(theme) {
  const body = document.body;
  body.classList.remove('theme-dark', 'theme-light');
  body.classList.add(theme === 'light' ? 'theme-light' : 'theme-dark');
  const sel = document.getElementById('themeSelect');
  if (sel) sel.value = theme === 'light' ? 'light' : 'dark';
}

export function setStatus(text, type = 'idle') {
  const statusEl = document.getElementById('status');
  const badge = statusEl?.querySelector('.status-badge');
  if (!statusEl) return;

  if (badge) {
    badge.className = `status-badge status-${type}`;
    badge.innerHTML = `<span class="status-dot ${type}"></span><span>${text}</span>`;
  } else {
    statusEl.textContent = text;
  }
}

export function setProgress(current, total) {
  const bar = document.getElementById('progressBar');
  if (!bar || !total) return;
  const pct = Math.min(100, Math.max(0, Math.round((current / total) * 100)));
  bar.style.width = `${pct}%`;
}

export function showToast(message, type = 'info', duration = 3000) {
  const toast = document.getElementById('toast');
  if (!toast) return;

  toast.textContent = message;
  toast.className = `toast show ${type}`;

  setTimeout(() => {
    toast.classList.remove('show');
  }, duration);
}

export function showError(message, details = null, stack = null) {
  const errorPanel = document.getElementById('errorPanel');
  if (!errorPanel) return;

  const errorMessage = errorPanel.querySelector('.error-message');
  const errorStack = errorPanel.querySelector('.error-stack');
  const toggleBtn = errorPanel.querySelector('.error-toggle-details');

  errorMessage.textContent = message;

  if (details || stack) {
    const detailsText = [
      details ? `Details: ${details}` : '',
      stack ? `Stack: ${stack}` : ''
    ].filter(Boolean).join('\n\n');

    errorStack.textContent = detailsText;
    toggleBtn.style.display = 'inline-block';
  } else {
    toggleBtn.style.display = 'none';
  }

  errorPanel.classList.remove('hidden');

  setTimeout(() => {
    hideError();
  }, 10000);
}

export function hideError() {
  const errorPanel = document.getElementById('errorPanel');
  if (errorPanel) {
    errorPanel.classList.add('hidden');
  }
}

export function clearError() {
  const errorPanel = document.getElementById('errorPanel');
  if (errorPanel) {
    errorPanel.querySelector('.error-message').textContent = '';
    errorPanel.querySelector('.error-stack').textContent = '';
    errorPanel.querySelector('.error-details').classList.add('hidden');
    errorPanel.querySelector('.error-toggle-details').textContent = 'Show Details';
  }
}

export function setButtonsDisabled(disabled) {
  const shouldDisable = disabled && document.getElementById('disableButtonsDuringAutomation')?.checked;
  document.querySelectorAll('button:not(#disableButtonsDuringAutomation)').forEach((btn) => {
    btn.disabled = shouldDisable;
  });
}

export function showHistoryLoading(show = true) {
  const loading = document.getElementById('historyLoading');
  const history = document.getElementById('history');
  if (show) {
    loading?.classList.remove('hidden');
    if (history) history.innerHTML = '';
  } else {
    loading?.classList.add('hidden');
  }
}

export function secToMs(v) {
  return typeof v === 'number' && !Number.isNaN(v) ? Math.round(v * 1000) : undefined;
}

export function msToSec(v) {
  return typeof v === 'number' && !Number.isNaN(v) ? v / 1000 : '';
}

import { showHistoryLoading, showToast } from './popup-dom-utils.js';
import { loadSettingsIntoUI } from './popup-settings.js';

function makeSignature(item) {
  return JSON.stringify((item.prompts || []).map((p) => p.trim()));
}

export function createHistoryRow(item, index, { onLoadPrompts } = {}) {
  const wrapper = document.createElement('div');
  wrapper.className = 'history-item';
  const title = item.title || (item.prompts?.slice(0, 1)?.[0] || '').slice(0, 80);
  const date = new Date(item.savedAt || Date.now()).toLocaleString();

  const row = document.createElement('div');
  row.className = 'history-row';

  const left = document.createElement('div');
  left.style.flex = '1';

  const titleEl = document.createElement('div');
  titleEl.style.whiteSpace = 'nowrap';
  titleEl.style.overflow = 'hidden';
  titleEl.style.textOverflow = 'ellipsis';
  titleEl.textContent = title;
  titleEl.title = (item.prompts || []).join('\n');

  const dateEl = document.createElement('div');
  dateEl.className = 'history-item-date';
  dateEl.textContent = date;

  left.appendChild(titleEl);
  left.appendChild(dateEl);

  const ctrls = document.createElement('div');
  ctrls.className = 'mini-controls';

  const loadBtn = document.createElement('button');
  loadBtn.textContent = 'Load';
  loadBtn.addEventListener('click', async () => {
    document.getElementById('prompts').value = (item.prompts || []).join('\n');
    if (item.settings) {
      await chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', settings: item.settings });
      await loadSettingsIntoUI();
    }
    if (typeof onLoadPrompts === 'function') {
      onLoadPrompts();
    }
  });

  const delBtn = document.createElement('button');
  delBtn.textContent = 'Delete';
  delBtn.addEventListener('click', async () => {
    await chrome.runtime.sendMessage({ type: 'DELETE_PROMPT_HISTORY', index });
    await loadHistoryIntoUI(onLoadPrompts);
  });

  ctrls.appendChild(loadBtn);
  ctrls.appendChild(delBtn);

  row.appendChild(left);
  row.appendChild(ctrls);
  wrapper.appendChild(row);
  return wrapper;
}

export async function loadHistoryIntoUI(onLoadPrompts) {
  try {
    const list = document.getElementById('history');
    const countBadge = document.getElementById('historyCount');
    const clearBtn = document.getElementById('clearHistoryBtn');

    if (!list) {
      console.error('[LoadHistory] History list element not found');
      return;
    }

    showHistoryLoading(true);

    await new Promise((r) => setTimeout(r, 300));

    const res = await chrome.runtime.sendMessage({ type: 'GET_PROMPT_HISTORY' });
    if (res?.ok) {
      const history = res.history || [];
      if (countBadge) {
        countBadge.textContent = `${history.length} item${history.length !== 1 ? 's' : ''}`;
      }
      if (clearBtn) {
        clearBtn.style.display = history.length > 0 ? 'block' : 'none';
      }
      history.forEach((item, idx) => {
        list.appendChild(createHistoryRow(item, idx, { onLoadPrompts }));
      });
    }

    showHistoryLoading(false);
  } catch (e) {
    console.error('[LoadHistory] Error:', e);
    showHistoryLoading(false);
  }
}

export async function importHistoryItems(importData) {
  if (!importData?.history || !Array.isArray(importData.history)) {
    throw new Error('Invalid JSON format');
  }

  const validItems = importData.history.filter((item) => {
    if (!item || typeof item !== 'object') return false;
    if (!Array.isArray(item.prompts) || item.prompts.length === 0) return false;
    return true;
  });

  const invalidCount = importData.history.length - validItems.length;
  if (validItems.length === 0) {
    return { imported: 0, duplicates: 0, invalid: invalidCount };
  }

  const { aiTaskSequencerHistory = [] } = await chrome.storage.local.get('aiTaskSequencerHistory');
  const existingSignatures = new Set(aiTaskSequencerHistory.map(makeSignature));

  const newItems = validItems.filter((item) => !existingSignatures.has(makeSignature(item)));
  const itemsWithTimestamp = newItems.map((item) => ({
    ...item,
    savedAt: item.savedAt || Date.now(),
  }));

  const mergedHistory = [...itemsWithTimestamp, ...aiTaskSequencerHistory].slice(0, 50);
  await chrome.storage.local.set({ aiTaskSequencerHistory: mergedHistory });

  return { imported: newItems.length, duplicates: validItems.length - newItems.length, invalid: invalidCount };
}

export async function clearHistory() {
  await chrome.storage.local.set({ aiTaskSequencerHistory: [] });
}

export async function exportHistory() {
  const res = await chrome.runtime.sendMessage({ type: 'GET_PROMPT_HISTORY' });
  if (!res?.ok || !res.history) return null;
  const exportData = {
    version: '1.0',
    exportedAt: new Date().toISOString(),
    history: res.history,
  };
  return exportData;
}

export async function saveHistoryItem(prompts, settings) {
  await chrome.runtime.sendMessage({
    type: 'SAVE_PROMPT_HISTORY',
    item: { prompts, settings },
  });
}

import { applyConsolePatch } from './popup-console-patch.js';
import { msToSec, secToMs, applyTheme } from './popup-dom-utils.js';

// Initialization and helpers for settings UI
export async function loadSettingsIntoUI() {
  try {
    const res = await chrome.runtime.sendMessage({ type: 'GET_SETTINGS' });
    if (res?.ok && res.settings) {
      const s = res.settings;
      applyTheme(s.theme || 'dark');
      document.getElementById('maxWaitSec').value = msToSec(s.maxWaitMs);
      document.getElementById('stableMinSec').value = msToSec(s.stableMinMs ?? s.stableMs);
      document.getElementById('stableMaxSec').value = msToSec(s.stableMaxMs ?? s.stableMs);
      document.getElementById('pollSec').value = msToSec(s.pollIntervalMs);
      document.getElementById('systemPrompt').value = s.systemPrompt || '';
      document.getElementById('prependSystemPrompt').checked = s.prependSystemPrompt !== false;
      document.getElementById('enableMaxWaitTimeout').checked = s.enableMaxWaitTimeout !== false;
      document.getElementById('enableStopWord').checked = s.enableStopWord === true;
      document.getElementById('stopWord').value = s.stopWord || '';
      document.getElementById('stopWordCaseSensitive').checked = s.stopWordCaseSensitive === true;
      document.getElementById('openNewChatPerPrompt').checked = s.openNewChatPerPrompt === true;
      document.getElementById('openNewChatPerPromptUrl').value = s.openNewChatPerPromptUrl || '';

      const stopWordContainer = document.getElementById('stopWordContainer');
      if (s.enableStopWord === true) {
        stopWordContainer.classList.remove('hidden');
      } else {
        stopWordContainer.classList.add('hidden');
      }
    }
  } catch (e) {
    console.error('[LoadSettings] Error:', e);
  }
}

export async function saveSettingsFromUI() {
  try {
    const maxWaitSec = Number(document.getElementById('maxWaitSec').value);
    const stableMinSec = Number(document.getElementById('stableMinSec').value);
    const stableMaxSec = Number(document.getElementById('stableMaxSec').value);
    const stableMinOrdered = Math.min(stableMinSec, stableMaxSec || stableMinSec);
    const stableMaxOrdered = Math.max(stableMinSec || stableMaxSec, stableMaxSec || stableMinSec);
    const pollSec = Number(document.getElementById('pollSec').value);
    const settings = {
      maxWaitMs: secToMs(maxWaitSec),
      stableMinMs: secToMs(stableMinOrdered),
      stableMaxMs: secToMs(stableMaxOrdered),
      pollIntervalMs: secToMs(pollSec),
      systemPrompt: document.getElementById('systemPrompt').value || '',
      prependSystemPrompt: document.getElementById('prependSystemPrompt').checked,
      enableMaxWaitTimeout: document.getElementById('enableMaxWaitTimeout').checked,
      enableStopWord: document.getElementById('enableStopWord').checked,
      stopWord: document.getElementById('stopWord').value || '',
      stopWordCaseSensitive: document.getElementById('stopWordCaseSensitive').checked,
      openNewChatPerPrompt: document.getElementById('openNewChatPerPrompt').checked,
      openNewChatPerPromptUrl: (document.getElementById('openNewChatPerPromptUrl').value || '').trim(),
    };
    await chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', settings });
  } catch (e) {
    console.error('[SaveSettings] Error:', e);
  }
}

export function initSettingsUI() {
  applyConsolePatch();

  const themeSelect = document.getElementById('themeSelect');
  if (themeSelect) {
    themeSelect.addEventListener('change', async (e) => {
      const val = e.target.value;
      applyTheme(val);
      try {
        await chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', settings: { theme: val } });
      } catch (err) {
        console.error('[ThemeChange] Error:', err);
      }
    });
  }

  ['maxWaitSec', 'stableMinSec', 'stableMaxSec', 'pollSec', 'systemPrompt', 'prependSystemPrompt', 'enableMaxWaitTimeout'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', saveSettingsFromUI);
  });

  const enableMaxWaitTimeoutCheckbox = document.getElementById('enableMaxWaitTimeout');
  if (enableMaxWaitTimeoutCheckbox) {
    enableMaxWaitTimeoutCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  const enableStopWordCheckbox = document.getElementById('enableStopWord');
  const stopWordContainer = document.getElementById('stopWordContainer');
  const stopWordInput = document.getElementById('stopWord');
  const stopWordCaseSensitiveCheckbox = document.getElementById('stopWordCaseSensitive');
  const openNewChatPerPromptCheckbox = document.getElementById('openNewChatPerPrompt');
  const openNewChatPerPromptUrlInput = document.getElementById('openNewChatPerPromptUrl');

  if (enableStopWordCheckbox) {
    enableStopWordCheckbox.addEventListener('change', () => {
      if (enableStopWordCheckbox.checked) {
        stopWordContainer.classList.remove('hidden');
        stopWordInput.focus();
      } else {
        stopWordContainer.classList.add('hidden');
      }
      saveSettingsFromUI();
    });
  }

  if (stopWordInput) {
    stopWordInput.addEventListener('input', saveSettingsFromUI);
  }

  if (stopWordCaseSensitiveCheckbox) {
    stopWordCaseSensitiveCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  if (openNewChatPerPromptCheckbox) {
    openNewChatPerPromptCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  if (openNewChatPerPromptUrlInput) {
    openNewChatPerPromptUrlInput.addEventListener('change', saveSettingsFromUI);
    openNewChatPerPromptUrlInput.addEventListener('blur', saveSettingsFromUI);
  }
}

import { applyConsolePatch } from './popup-console-patch.js';
import { parsePrompts, setStatus, setProgress, showToast, showError, hideError, clearError, setButtonsDisabled, secToMs, PROMPT_SEPARATOR } from './popup-dom-utils.js';
import { loadSettingsIntoUI, saveSettingsFromUI, initSettingsUI } from './popup-settings.js';
import { loadHistoryIntoUI, importHistoryItems, clearHistory, exportHistory, saveHistoryItem } from './popup-history.js';

applyConsolePatch();

const separatorInput = document.getElementById('separatorInput');
const resolveSeparator = (raw) => {
  if (!raw || typeof raw !== 'string') return PROMPT_SEPARATOR;
  // Support literal "\n" sequences entered by the user
  return raw.replace(/\\n/g, '\n');
};

async function getActiveTabId() {
  const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
  return tabs?.[0]?.id;
}

const pauseBtn = document.getElementById('pauseBtn');
const resumeBtn = document.getElementById('resumeBtn');

function updateControlButtons(status = {}) {
  const running = !!status.running;
  const paused = !!status.paused;

  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');

  if (startBtn) startBtn.disabled = running;
  if (stopBtn) stopBtn.disabled = !running;

  if (pauseBtn) {
    pauseBtn.style.display = running && !paused ? 'inline-block' : 'none';
    pauseBtn.disabled = !running || paused;
  }
  if (resumeBtn) {
    resumeBtn.style.display = running && paused ? 'inline-block' : 'none';
    resumeBtn.disabled = !running || !paused;
  }
}

async function refreshStatus() {
  try {
    const res = await chrome.runtime.sendMessage({ type: 'AUTOMATION_STATUS_REQUEST' });
    if (res?.ok && res.status) {
      const { running, paused, currentIndex, total, recoveryAttempts } = res.status;
      setProgress(running ? currentIndex : total, total);
      setButtonsDisabled(running && !paused);
      updateControlButtons(res.status);
      if (paused) {
        setStatus(`Paused at prompt ${currentIndex + 1} of ${total}`, 'paused');
      } else if (running) {
        if (recoveryAttempts > 0) {
          setStatus(`Recovering... (attempt ${recoveryAttempts}/3) - Prompt ${currentIndex + 1} of ${total}`, 'running');
        } else {
          setStatus(`Running prompt ${currentIndex + 1} of ${total}...`, 'running');
        }
      } else if (total > 0 && currentIndex >= total) {
        setStatus('Complete', 'idle');
      } else {
        setStatus('Idle', 'idle');
      }
    }
  } catch (e) {
    console.error('[RefreshStatus] Error:', e);
  }
}

initSettingsUI();

async function startAutomation() {
  try {
    // Check if automation is already running
    const statusRes = await chrome.runtime.sendMessage({ type: 'AUTOMATION_STATUS_REQUEST' });
    if (statusRes?.ok && statusRes.status?.running) {
      showToast('Automation is already running. Stop it first.', 'error');
      setStatus(`Running prompt ${statusRes.status.currentIndex + 1} of ${statusRes.status.total}...`, 'running');
      return;
    }

    const textarea = document.getElementById('prompts');
    const separatorInput = document.getElementById('separatorInput');
    const separator = resolveSeparator(separatorInput?.value);
    const prompts = parsePrompts(textarea.value, separator);
    if (prompts.length === 0) {
      setStatus('Please enter at least one prompt.');
      return;
    }
    const tabId = await getActiveTabId();
    if (!tabId) {
      setStatus('No active tab found.');
      return;
    }
    setStatus('Starting...');
    hideError(); // Clear any previous error
    // Get current settings and include them in START_AUTOMATION to avoid race conditions
    await saveSettingsFromUI();
    const settingsRes = await chrome.runtime.sendMessage({ type: 'GET_SETTINGS' });
    const currentSettings = settingsRes?.settings || {};
    const res = await chrome.runtime.sendMessage({ type: 'START_AUTOMATION', prompts, tabId, options: currentSettings });
    if (res?.ok) {
      setStatus(`Running prompt 1 of ${prompts.length}...`, 'running');
      setProgress(0, prompts.length);
      updateControlButtons({ running: true, paused: false });
      await chrome.runtime.sendMessage({ type: 'SAVE_PROMPT_HISTORY', item: { prompts, settings: currentSettings } });
    } else {
      setStatus(`Failed to start: ${res?.error || 'Unknown error'}`, 'error');
      showToast(res?.error || 'Failed to start', 'error');
    }
  } catch (e) {
    console.error('[StartAutomation] Error:', e);
    setStatus(`Failed to start: ${e}`, 'error');
  }
}

document.getElementById('startBtn').addEventListener('click', startAutomation);

