}

.toast.info {
  border-color: var(--accent);
  background: rgba(16, 185, 129, 0.1);
  color: var(--accent);
}

/* Button States */
button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

button:disabled:hover {
  border-color: var(--border);
  color: var(--text);
}

