  font-size: 11px;
  background: var(--input-bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  cursor: pointer;
  transition: all 0.2s;
}

.error-copy-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

/* Stop Word Container */
.stop-word-container {
  background: rgba(59, 130, 246, 0.05);
  border: 1px solid rgba(59, 130, 246, 0.2);
  border-radius: 6px;
  padding: 10px;
  margin-top: 8px;
}

.stop-word-container.hidden {
