  methods.forEach((method) => {
    if (typeof console[method] === 'function') {
      const original = console[method].bind(console);
      console[method] = (...args) => {
        if (args.length > 0 && typeof args[0] === 'string') {
          original(`${PREFIX} ${args[0]}`, ...args.slice(1));
        } else {
          original(PREFIX, ...args);
        }
      };
